create or replace function app.financial_period_close_readiness(p_period_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare fp public.financial_periods%rowtype;v_pending bigint;v_unresolved bigint;v_confirmed bigint;v_matched bigint;v_unmatched bigint;v_report public.financial_reports%rowtype;v_rep_rev numeric:=0;v_rep_exp numeric:=0;v_period_ended boolean;t jsonb;v_ok boolean:=false;
begin if not app.has_permission('financial_reports.view')and not app.has_permission('financial_periods.close')then raise exception 'Missing financial period readiness permission.' using errcode='42501';end if;select * into fp from public.financial_periods where id=p_period_id;if fp.id is null then raise exception 'Financial period not found.' using errcode='P0002';end if;perform app.assert_canonical_financial_period(fp.id);v_period_ended:=fp.ends_on<app.accounting_date(now());t:=app.financial_period_accounting_totals(fp.id);
select count(*)into v_pending from public.finance_payments p where p.status='pending' and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on;select count(*)into v_unresolved from public.finance_refunds r join public.finance_payments p on p.id=r.payment_id where r.status in('requested','approved')and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on;select count(*)into v_confirmed from public.finance_payments p where p.status='confirmed' and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on;select count(*)into v_matched from public.finance_payments p where p.status='confirmed' and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on and exists(select 1 from public.finance_bank_reconciliations br where br.payment_id=p.id and br.status='matched' and br.invoice_id is not distinct from p.invoice_id and br.bank_amount is not distinct from p.amount);v_unmatched:=greatest(v_confirmed-v_matched,0);
select * into v_report from public.financial_reports fr where fr.financial_period_id=fp.id and fr.status='approved' order by fr.updated_at desc limit 1;if v_report.id is not null and v_report.current_version_id is not null then select coalesce(max(amount)filter(where line_key='revenue_total'),0),coalesce(max(amount)filter(where line_key='expense_total'),0)into v_rep_rev,v_rep_exp from public.financial_line_items where financial_report_version_id=v_report.current_version_id;v_ok:=v_rep_rev=(t->>'net_revenue')::numeric and v_rep_exp=(t->>'expense_total')::numeric;end if;
return t||jsonb_build_object('period_id',fp.id,'status',fp.status,'period_ended',v_period_ended,'pending_payments',v_pending,'unresolved_refunds',v_unresolved,'confirmed_payments',v_confirmed,'matched_reconciliations',v_matched,'unmatched_confirmed_payments',v_unmatched,'confirmed_payment_amount',(t->>'confirmed_payments')::numeric,'processed_refund_amount',(t->>'processed_refunds')::numeric,'net_receipts',(t->>'net_revenue')::numeric,'recorded_expenses',(t->>'expense_total')::numeric,'approved_report_id',v_report.id,'approved_report_present',v_report.id is not null,'reported_revenue',v_rep_rev,'reported_expenses',v_rep_exp,'report_reconciled',v_ok,'ready_to_close',fp.status='open' and v_period_ended and v_pending=0 and v_unresolved=0 and v_unmatched=0 and v_report.id is not null and v_ok,'ready_to_lock',fp.status='closed' and v_report.id is not null);end $$;

create or replace function app.close_financial_period(p_period_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare fp public.financial_periods%rowtype;v_report public.financial_reports%rowtype;v_rep_rev numeric;v_rep_exp numeric;t jsonb;
begin if not app.has_permission('financial_periods.close')then raise exception 'Missing permission: financial_periods.close' using errcode='42501';end if;select * into fp from public.financial_periods where id=p_period_id for update;if fp.id is null then raise exception 'Financial period not found.' using errcode='P0002';end if;perform app.assert_canonical_financial_period(fp.id);if fp.status<>'open'then raise exception 'Only open financial periods can be closed.' using errcode='23514';end if;if fp.ends_on>=app.accounting_date(now())then raise exception 'Financial period can only be closed after its end date (%).',fp.ends_on using errcode='23514';end if;
if exists(select 1 from public.finance_payments p where p.status='pending' and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on)then raise exception 'Financial period has pending payments.' using errcode='23514';end if;if exists(select 1 from public.finance_refunds r join public.finance_payments p on p.id=r.payment_id where r.status in('requested','approved')and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on)then raise exception 'Financial period has unresolved refund requests.' using errcode='23514';end if;if exists(select 1 from public.finance_payments p left join public.finance_bank_reconciliations br on br.payment_id=p.id and br.status='matched' where p.status='confirmed' and p.received_at is not null and app.accounting_date(p.received_at)between fp.starts_on and fp.ends_on and(br.id is null or br.invoice_id is distinct from p.invoice_id or br.bank_amount is distinct from p.amount))then raise exception 'Every confirmed payment in the period must have a matching bank reconciliation for the same invoice and amount.' using errcode='23514';end if;if exists(select 1 from public.financial_reports fr where fr.financial_period_id=fp.id and fr.status in('draft','review'))then raise exception 'Financial period has an unfinished financial report workflow.' using errcode='23514';end if;
select * into v_report from public.financial_reports fr where fr.financial_period_id=fp.id and fr.status='approved' order by fr.updated_at desc limit 1 for update;if v_report.id is null or v_report.current_version_id is null then raise exception 'Financial period requires an approved financial report before close.' using errcode='23514';end if;t:=app.financial_period_accounting_totals(fp.id);select coalesce(max(amount)filter(where line_key='revenue_total'),0),coalesce(max(amount)filter(where line_key='expense_total'),0)into v_rep_rev,v_rep_exp from public.financial_line_items where financial_report_version_id=v_report.current_version_id;if v_rep_rev is distinct from(t->>'net_revenue')::numeric or v_rep_exp is distinct from(t->>'expense_total')::numeric then raise exception 'Approved financial report no longer reconciles with canonical ledger including posted adjustments.' using errcode='23514';end if;
perform set_config('app.financial_period_transition','allowed',true);update public.financial_periods set status='closed',updated_at=now()where id=fp.id;perform set_config('app.financial_period_transition','',true);insert into public.audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,summary,changes)values(auth.uid(),app.current_actor_type(),'financial_period.closed','financial_period',fp.id,'Financial period closed after canonical reconciliation including adjustments.',jsonb_build_object('starts_on',fp.starts_on,'ends_on',fp.ends_on,'accounting_timezone',app.accounting_timezone(),'confirmed_payments',(t->>'confirmed_payments')::numeric,'processed_refunds',(t->>'processed_refunds')::numeric,'revenue_adjustments',(t->>'revenue_adjustments')::numeric,'expense_adjustments',(t->>'expense_adjustments')::numeric,'net_revenue',(t->>'net_revenue')::numeric,'recorded_expenses',(t->>'expense_total')::numeric,'report_id',v_report.id));end $$;